-- Function: public.fn_get_pending_teacher_handovers_by_branch
-- Backup generated on 2026-10-25 20:33:37

CREATE OR REPLACE FUNCTION public.fn_get_pending_teacher_handovers_by_branch(p_tenant_id uuid, p_branch_id uuid)  RETURNS TABLE(id uuid, tenant_id uuid, organization_id uuid, branch_id uuid, classroom_id uuid, handover_date date, shift_type character varying, outgoing_teacher_user_id uuid, outgoing_teacher_name character varying, incoming_teacher_user_id uuid, incoming_teacher_name character varying, summary_notes text, child_specific_notes text, outstanding_care_tasks text, pending_followups text, status character varying, is_critical boolean, acknowledged_at timestamp with time zone, acknowledged_by_user_id uuid, acknowledged_by_name character varying, acknowledgement_notes text, created_at timestamp with time zone, updated_at timestamp with time zone, classroom_name character varying, branch_name character varying)  LANGUAGE sql  STABLE AS $function$     SELECT th.id, th.tenant_id, th.organization_id, th.branch_id, th.classroom_id,            th.handover_date, th.shift_type, th.outgoing_teacher_user_id, th.outgoing_teacher_name,            th.incoming_teacher_user_id, th.incoming_teacher_name, th.summary_notes,            th.child_specific_notes, th.outstanding_care_tasks, th.pending_followups,            th.status, th.is_critical, th.acknowledged_at, th.acknowledged_by_user_id,            th.acknowledged_by_name, th.acknowledgement_notes, th.created_at, th.updated_at,            cl.name AS classroom_name,            b.name AS branch_name     FROM teacher_handovers th     JOIN classrooms cl ON th.classroom_id = cl.id     JOIN branches b ON th.branch_id = b.id     WHERE th.tenant_id = p_tenant_id        AND th.branch_id = p_branch_id        AND th.status = 'PendingAcknowledgement'     ORDER BY th.is_critical DESC, th.created_at DESC; $function$ ;
